let BarrierLogo: Sprite = null

namespace color {
    //%fixedInstance whenUsed block="BARRIER"
    export const Barrier = bufferToPalette(hex`
        000000
        FFFFFF
        C2D1FF
        85A3FF
        4754FF
        2D00D1
        12009E
        000080
        000040
        F53DF5
        990099
        BABABA
        575757
        BD0000
        000020
        000000

    `);
}

//Logo pallete fade
function FadeToLogoPalette() {
    BarrierLogo = sprites.create(assets.image`BARRIERLOGO`, SpriteKind.Player)
    BarrierLogo.setScale(3, ScaleAnchor.Middle)
    color.setPalette(
        color.Black
    )
    color.startFadeFromCurrent(color.Barrier)
    music.play(music.createSong(hex``), music.PlaybackMode.UntilDone)
    color.startFadeFromCurrent(color.Black)
    color.pauseUntilFadeDone()
    sprites.destroy(BarrierLogo)
}
